{"command":"python3 - <<'EOF'
from datetime import date
lan = date(2026,2,3)
def lim(m, n=5):  # marco + 5 anos
    try: return m.replace(year=m.year+n)
    except ValueError: return m.replace(year=m.year+n, day=28)
def lastday(m, n=5):
    l = lim(m,n)
    from datetime import timedelta
    return l - timedelta(days=1)  # último dia do quinquênio

scen = {
 "3T/2020 (sem pagto)": [
    ("173 I (devida: Tema163/Sum555); venc. out/2020 -> marco 01/01/2021", date(2021,1,1)),
    ("150 §4º hipótese; FG fim trim 30/09/2020", date(2020,9,30)),
    ("173 §único (FORA DA BIBLIOTECA) se simul. praticada em 2020 -> 01/01/2021", date(2021,1,1)),
 ],
 "4T/2020 (pagto parcial 29/01/2021)": [
    ("150 §4º (devida: Tema163); FG fim trim 31/12/2020", date(2020,12,31)),
    ("150 §4º leitura FG=data vencimento 29/01/2021", date(2021,1,29)),
    ("173 I hipótese: venc. jan/2021 -> lançamento poderia ocorrer em 2021 -> marco 01/01/2022", date(2022,1,1)),
    ("173 §único (FORA) se simul. em 2021 -> marco 01/01/2022", date(2022,1,1)),
 ],
 "1T/2021 (pagto parcial 30/04/2021)": [
    ("150 §4º (devida); FG fim trim 31/03/2021", date(2021,3,31)),
    ("150 §4º leitura venc. 30/04/2021", date(2021,4,30)),
    ("173 I hipótese: venc. abr/2021 -> marco 01/01/2022", date(2022,1,1)),
 ],
 "2T/2021 (sem pagto)": [
    ("173 I (devida); venc. jul/2021 -> marco 01/01/2022", date(2022,1,1)),
    ("150 §4º hipótese; FG 30/06/2021", date(2021,6,30)),
 ],
}
for per, lst in scen.items():
    print("##", per)
    for name, marco in lst:
        L = lastday(marco)
        d = (lan - L).days
        tag = f"DECAIU {d} dias" if lan > L else f"NO PRAZO (folga de {-d} dias)"
        print(f"   {name:85} marco {marco} -> limite {L} | lançamento {lan}: {tag}")
EOF"}

